    /**
     * Handles create a BOM.
     * @param		BOM	bOM
     * @return		CompletableFuture<UUID> 
     */
	@PostMapping("/create")
    public CompletableFuture<UUID> create( @RequestBody(required=true) CreateBOMCommand command ) {
		CompletableFuture<UUID> completableFuture = null;
		try {
			completableFuture = service.createBOM( command );
        }
        catch( Throwable exc ) {
        	LOGGER.log( Level.WARNING, exc.getMessage(), exc );        	
        }
		
		return completableFuture;
    }

    /**
     * Handles updating a BOM.  if no key provided, calls create, otherwise calls save
     * @param		BOM bOM
     * @return		CompletableFuture<Void>
     */
	@PutMapping("/update")
    public CompletableFuture<Void> update( @RequestBody(required=true) UpdateBOMCommand command ) {
		CompletableFuture<Void> completableFuture = null;
		try {                        	        
			// -----------------------------------------------
			// delegate the UpdateBOMCommand
			// -----------------------------------------------
			completableFuture = service.updateBOM(command);;
	    }
	    catch( Throwable exc ) {
	    	LOGGER.log( Level.WARNING, "BOMController:update() - successfully update BOM - " + exc.getMessage());        	
	    }		
		
		return completableFuture;
	}
 
    /**
     * Handles deleting a BOM entity
     * @param		command ${class.getDeleteCommandAlias()}
     * @return		CompletableFuture<Void>
     */
    @DeleteMapping("/delete")    
    public CompletableFuture<Void> delete( @RequestParam(required=true) UUID bOMId  ) {
    	CompletableFuture<Void> completableFuture = null;
		DeleteBOMCommand command = new DeleteBOMCommand( bOMId );

    	try {
        	completableFuture = service.delete( command );
    		LOGGER.log( Level.WARNING, "Successfully deleted BOM with key " + command.getBOMId() );
        }
        catch( Throwable exc ) {
        	LOGGER.log( Level.WARNING, exc.getMessage() );
        }
        
        return completableFuture;
	}        
	

